Every error in the abnormal window falls in the first minute, which is when config-service was down. That points to one root cause, so I'm ready to write up the answer.

{
  "root_causes": [
    {
      "service": "ts-config-service",
      "fault_kind": "pod_failure",
      "evidence": [
        {"kind": "metric", "sql": "SELECT date_trunc('minute', time) m, min(value) mn, max(value) mx FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'ts-config%' AND metric='k8s.container.restarts' GROUP BY 1 ORDER BY 1", "claim": "Config-service container restart counter rises from 0 to 1 at the start of the abnormal window, then stays at 1."},
        {"kind": "trace", "sql": "SELECT date_trunc('minute', time) m, count(*) n FROM abnormal_traces WHERE service_name='ts-config-service' GROUP BY 1 ORDER BY 1", "claim": "Config-service emits only 36 spans in the first minute versus about 2,000 per minute afterwards, a gap consistent with a brief outage then recovery."},
        {"kind": "trace", "sql": "SELECT date_trunc('minute', time) m, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces c WHERE c.service_name='ts-seat-service' AND c.span_name LIKE 'GET%' AND c.attr_span_kind='Client' GROUP BY 1 ORDER BY 1", "claim": "Seat-service GET calls to config-service fail mostly in the first minute (111 of 131), then almost never."},
        {"kind": "log", "sql": "SELECT message, count(*) n FROM abnormal_logs WHERE service_name='ts-seat-service' AND level='SEVERE' GROUP BY 1", "claim": "Seat-service logs 'Connection refused' on GET to ts-config-service configs endpoint, 116 times."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-config-service", "to": "ts-seat-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, avg(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) caller_err FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-seat-service' AND c.span_name LIKE 'GET%' AND c.attr_span_kind='Client' GROUP BY ALL", "claim": "About 5.8% of seat-service client GET calls to config-service end in error."}]},
    {"from": "ts-seat-service", "to": "ts-travel-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, avg(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-service' AND s.service_name='ts-seat-service' GROUP BY ALL", "claim": "Seat-service left_tickets responses called by travel-service fail about 6% of the time in the abnormal window."}]},
    {"from": "ts-seat-service", "to": "ts-travel2-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, avg(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) caller_err FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel2-service' AND s.service_name='ts-seat-service' GROUP BY ALL", "claim": "Travel2-service calls to seat-service left_tickets fail about 12.5% of the time."}]},
    {"from": "ts-travel-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, avg(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) caller_err FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-route-plan-service' AND s.service_name='ts-travel-service' GROUP BY ALL", "claim": "Route-plan calls to travel-service trips/left fail about 20% of the time in the abnormal window."}]},
    {"from": "ts-travel2-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, avg(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) caller_err FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-route-plan-service' AND s.service_name='ts-travel2-service' GROUP BY ALL", "claim": "Route-plan calls to travel2-service trips/left and trip_detail fail 14-23% of the time."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, avg(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) caller_err, quantile_cont(c.duration/1e6,0.95) p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-plan-service' AND s.service_name='ts-route-plan-service' GROUP BY ALL", "claim": "Travel-plan calls to route-plan routePlan endpoints fail 26-34% of the time with p95 near 3 seconds."}]},
