    {"from": "ts-travel-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, avg(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-travel-service' GROUP BY ALL", "claim": "Ui-dashboard calls to travel-service fail about 19% of the time in the abnormal window."}]}
